// Un mini-DOM: cada nodo es un objeto con padre e hijos.
function el(nombre, atrib = {}, ...hijos) {
  const n = { tipo: 1, nombre, atrib, padre: null, hijos: [] };
  for (const h of hijos) agregar(n, typeof h === 'string' ? { tipo: 3, texto: h, padre: null } : h);
  return n;
}
function agregar(padre, hijo) {
  if (hijo.padre) quitar(hijo);          // un nodo solo puede estar en un lugar
  hijo.padre = padre;
  (padre.hijos ??= []).push(hijo);
  return hijo;
}
function quitar(n) {
  n.padre.hijos.splice(n.padre.hijos.indexOf(n), 1);
  n.padre = null;
}
// Orden de documento = recorrido en profundidad, padre antes que hijos (preorden).
function* recorrer(n) {
  yield n;
  for (const h of n.hijos ?? []) yield* recorrer(h);
}
function coincide(n, sel) {              // solo "etiqueta", ".clase" o "#id"
  if (n.tipo !== 1) return false;
  if (sel[0] === '#') return n.atrib.id === sel.slice(1);
  if (sel[0] === '.') return (n.atrib.class ?? '').split(' ').includes(sel.slice(1));
  return n.nombre === sel;
}
const querySelector = (raiz, sel) => [...recorrer(raiz)].find(n => coincide(n, sel)) ?? null;
const querySelectorAll = (raiz, sel) => [...recorrer(raiz)].filter(n => coincide(n, sel));  // una foto: no se actualiza
const texto = n => [...recorrer(n)].filter(x => x.tipo === 3).map(x => x.texto).join('');

