const N = 3000;
const ul = document.createElement('ul');
document.body.append(ul);
const crear = i => { const li = document.createElement('li'); li.textContent = 'Pedido ' + i; return li; };
const pruebas = {
  'A) append uno por uno, sin leer medidas': () => { for (let i = 0; i < N; i++) ul.append(crear(i)); },
  'B) append uno por uno, leyendo offsetHeight cada vuelta': () => { for (let i = 0; i < N; i++) { ul.append(crear(i)); void ul.offsetHeight; } },
  'C) DocumentFragment y un solo append': () => { const f = document.createDocumentFragment(); for (let i = 0; i < N; i++) f.append(crear(i)); ul.append(f); },
  'D) innerHTML con un string armado': () => { let s = ''; for (let i = 0; i < N; i++) s += '<li>Pedido ' + i + '</li>'; ul.innerHTML = s; },
};
for (const [nombre, f] of Object.entries(pruebas)) {
  const tiempos = [];
  for (let rep = 0; rep < 9; rep++) {
    ul.replaceChildren();
    await new Promise(r => requestAnimationFrame(() => r()));
    const t0 = performance.now();
    f();
    void ul.offsetHeight;                          // que el layout final entre en la medición
    tiempos.push(performance.now() - t0);
  }
  tiempos.sort((x, y) => x - y);
  console.log(nombre.padEnd(58), tiempos[4].toFixed(1).padStart(7), 'ms (mediana de 9)');
}

